draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var cx = W * 0.30, cy = H * 0.42, Rp = Math.min(W, H) * 0.16;

// Earth
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.8;
ctx.beginPath(); ctx.arc(cx, cy, Rp, 0, 6.2832); ctx.stroke();
ctx.fillStyle = C.ink; ctx.fillText("Earth", cx - 16, cy + 4);
ctx.fillStyle = C.faint; ctx.fillText("radius R", cx - 24, cy + 18);

// Moon direction marker on the right
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cx + Rp, cy); ctx.lineTo(W - 12, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("to Moon, distance d", W - 132, cy - 8);

function arrow(x, y, len, color, wid) {
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + len, y); ctx.stroke();
  var s = len > 0 ? 1 : -1, hx = x + len;
  ctx.beginPath();
  ctx.moveTo(hx, y); ctx.lineTo(hx - 7 * s, y - 4); ctx.lineTo(hx - 7 * s, y + 4);
  ctx.closePath(); ctx.fill();
}

// three nearly equal pulls
var base = W * 0.20;
var ys = [cy - Rp * 0.0 - 0, cy, cy];
var near = cx + Rp, far = cx - Rp;
var yNear = cy - 46, yCen = cy - 4, yFar = cy + 38;

ctx.fillStyle = C.ink;
ctx.fillText("Moon's pull on three points, drawn to scale:", 12, 18);

arrow(near + 6, yNear, base * 1.02, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("near side:  GM/(d−R)²", near + 10, yNear - 8);

arrow(cx + 6, yCen, base, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("centre:  GM/d²", cx + 10, yCen - 8);

arrow(far + 6, yFar, base * 0.98, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("far side:  GM/(d+R)²", far + 10, yFar - 8);

// residual after subtracting the centre value
var ry = H - 30;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(12, ry - 26); ctx.lineTo(W - 12, ry - 26); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("subtract the centre arrow from each, then magnify ×" + p.mag.toFixed(0) + ":", 12, ry - 11);

var resid = base * 0.02 * p.mag / 30;
arrow(cx + Rp + 6, ry + 6, resid, C.accent, 2.4);
arrow(cx - Rp - 6, ry + 6, -resid, C.accent, 2.4);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, ry + 6, Rp * 0.35, 0, 6.2832); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("2GMR/d³ outward, both ends — a stretch", cx + Rp + 14, ry + 22);

out.note = "Each long arrow is about 3.3e-5 m/s²; the difference between them is only 1.1e-6 m/s², about 3% as long. Shown magnified ×" + p.mag.toFixed(0) + ".";
